import{_ as s,o as e,c as a,a3 as t}from"./chunks/framework.vDgOMd_y.js";const k=JSON.parse('{"title":"Using Kimi Code CLI in IDEs","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/ides.md","filePath":"en/guides/ides.md"}'),n={name:"en/guides/ides.md"};function o(l,i,h,r,p,d){return e(),a("div",null,[...i[0]||(i[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/ides.md for this page in Markdown format</div><h1 id="using-kimi-code-cli-in-ides" tabindex="-1">Using Kimi Code CLI in IDEs <a class="header-anchor" href="#using-kimi-code-cli-in-ides" aria-label="Permalink to &quot;Using Kimi Code CLI in IDEs&quot;">​</a></h1><p>Kimi Code CLI supports integration into IDEs via the <a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">Agent Client Protocol (ACP)</a>, letting you use AI-assisted coding directly inside your editor.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before configuring your IDE, make sure Kimi Code CLI is installed and you have completed the login setup.</p><p>The ACP adapter is exposed as the <code>kimi acp</code> subcommand. The IDE launches it as a child process and communicates over stdin/stdout using JSON-RPC. Each time the IDE creates a session, the CLI reuses its existing authentication state — no need to log in again.</p><div class="tip custom-block"><p class="custom-block-title">Path note</p><p>Child processes launched from an IDE GUI on macOS typically do <strong>not</strong> inherit the terminal shell&#39;s <code>PATH</code>. If <code>kimi</code> is not in a system directory like <code>/usr/local/bin</code>, use the absolute path in your IDE configuration. Run <code>which kimi</code> in a terminal to find the active path.</p></div><h2 id="using-kimi-code-cli-in-zed" tabindex="-1">Using Kimi Code CLI in Zed <a class="header-anchor" href="#using-kimi-code-cli-in-zed" aria-label="Permalink to &quot;Using Kimi Code CLI in Zed&quot;">​</a></h2><p><a href="https://zed.dev/" target="_blank" rel="noreferrer">Zed</a> is a modern editor with native ACP support.</p><p>Add the following to Zed&#39;s config file at <code>~/.config/zed/settings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Configuration fields:</p><ul><li><code>type</code>: fixed value <code>&quot;custom&quot;</code></li><li><code>command</code>: path to the Kimi Code CLI executable. If <code>kimi</code> is not on <code>PATH</code>, use the full path (e.g. <code>/Users/you/.local/bin/kimi</code>).</li><li><code>args</code>: startup arguments. The <code>acp</code> subcommand switches the CLI into ACP mode.</li><li><code>env</code>: additional environment variables; usually leave this empty. Zed injects a default environment automatically.</li></ul><p>After saving, open a new conversation in Zed&#39;s Agent panel and it will launch a <code>Kimi Code CLI</code> ACP subprocess using the configuration above. MCP servers declared in Zed&#39;s <code>agent_servers</code> section are also forwarded to the kimi side via the ACP protocol.</p><h2 id="using-kimi-code-cli-in-jetbrains-ides" tabindex="-1">Using Kimi Code CLI in JetBrains IDEs <a class="header-anchor" href="#using-kimi-code-cli-in-jetbrains-ides" aria-label="Permalink to &quot;Using Kimi Code CLI in JetBrains IDEs&quot;">​</a></h2><p>JetBrains IDEs (IntelliJ IDEA, PyCharm, WebStorm, etc.) support ACP through the AI chat plugin.</p><p>If you do not have a JetBrains AI subscription, you can enable <code>llm.enable.mock.response</code> in the Registry to access the AI chat panel in ACP-only scenarios. Press Shift twice and search for &quot;Registry&quot; to open it.</p><p>In the AI chat panel menu, click <strong>Configure ACP agents</strong> and add the following configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.local/bin/kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JetBrains is strict about the <code>command</code> field — always use an <strong>absolute path</strong>, which you can get by running <code>which kimi</code> in a terminal. After saving, <code>Kimi Code CLI</code> will appear in the AI chat&#39;s agent selector.</p><h2 id="using-kimi-code-cli-in-paseo" tabindex="-1">Using Kimi Code CLI in Paseo <a class="header-anchor" href="#using-kimi-code-cli-in-paseo" aria-label="Permalink to &quot;Using Kimi Code CLI in Paseo&quot;">​</a></h2><p><a href="https://paseo.sh/" target="_blank" rel="noreferrer">Paseo</a> is a self-hosted orchestrator that runs and supervises agent CLIs from your desktop, web, and mobile. It connects to Kimi Code CLI over ACP, the same way an IDE does.</p><p>Pick <strong>Kimi Code CLI</strong> from Paseo&#39;s built-in ACP provider catalog, or add a custom provider in <code>~/.paseo/config.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;extends&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Paseo&#39;s generic ACP adapter does not drive the login flow, so complete the terminal login first (see <a href="#prerequisites">Prerequisites</a>) — otherwise session creation fails with <code>Authentication required</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Session disconnects immediately / IDE shows &quot;agent exited&quot;</strong>: usually a wrong <code>command</code> path or a missing login. Run <code>kimi acp</code> in a terminal first to verify — if it blocks waiting for stdin, the CLI itself is fine and the problem is in the IDE configuration; if it exits immediately with an error, follow the error message (most commonly you need to run <code>/login</code>).</li><li><strong>IDE shows &quot;auth required&quot;</strong>: the CLI has no usable authentication token. Exit the IDE, run <code>kimi</code> in a terminal to complete login, then restart the IDE.</li><li><strong>MCP tools not visible</strong>: check the <a href="./../reference/kimi-acp.html"><code>kimi acp</code> reference</a> capability table to confirm that the MCP transport type configured in your IDE is supported. The Kimi Code CLI ACP adapter currently supports <code>http</code>, <code>stdio</code>, and <code>sse</code> transports; <code>acp</code> transport MCP servers are silently dropped and a warning is written to the log.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../reference/kimi-acp.html">kimi acp reference</a> — ACP capability matrix and method coverage details</li><li><a href="./../reference/kimi-command.html">kimi command reference</a> — full subcommand list</li></ul>`,29)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
